effect.shader:
float hash(vec2 p, float semente) {
    return fract(sin(dot(p, vec2(127.1, 311.7)) + semente * 43.71) * 43758.5453);
}

void main() {
    vec2 counts = vec2(max(countX, 1.0), max(countY, 1.0));
    vec2 grid = acScreenNorm * counts;
    vec2 cell = floor(grid);
    vec2 local = fract(grid) - 0.5; // -0.5..0.5, centralizado na própria célula

    float anguloAleatorio = (hash(cell, seed) - 0.5) * 2.0 * radians(rotationAmount);
    vec2 deslocAleatorio = vec2(
        hash(cell + vec2(17.0, 0.0), seed) - 0.5,
        hash(cell + vec2(0.0, 29.0), seed) - 0.5
    ) * offsetAmount;
    float escalaAleatoria = 1.0 + (hash(cell + vec2(41.0, 5.0), seed) - 0.5) * 2.0 * scaleAmount;

    // A volta: desfaz o giro e a escala DESTA célula, pra achar de onde a
    // amostra deveria vir na imagem original.
    float c = cos(-anguloAleatorio);
    float s = sin(-anguloAleatorio);
    vec2 local2 = mat2(c, -s, s, c) * (local / max(escalaAleatoria, 0.05)) - deslocAleatorio;

    vec2 uv = (cell + local2 + 0.5) / counts;

    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        fragColor = vec4(0.0);
        return;
    }

    fragColor = texture(inputImg, uv);
}
